<script lang="ts">import {translate,dateLocale} from '$lib/i18n';import {page} from '$app/state';const t=(text:string)=>translate(page.data.lang,text);import {enhance} from '$app/forms';import AppHeader from '$lib/AppHeader.svelte';import {LockKeyhole,ArrowRight,LoaderCircle} from 'lucide-svelte';import type {PageProps} from './$types';let {form}:PageProps=$props();let pending=$state(false);</script>
<svelte:head><title>{t("Choose a new password — Rose Atelier")}</title><meta name="robots" content="noindex"/></svelte:head>
<div class="app-shell"><AppHeader/><main class="password-main"><section class="auth-card"><span class="auth-flower"><LockKeyhole size={25}/></span><span class="eyebrow">{t("A FRESH START")}</span><h1>{t("A new password,")}<br/><i>{t("a little peace of mind.")}</i></h1><p class="auth-intro">{t("Choose a new password to keep your little lookbook yours.")}</p>{#if form?.message}<div class="auth-message error" role="alert">{t(form.message)}</div>{/if}<form class="email-form" method="POST" use:enhance={()=>{pending=true;return async({update})=>{try{await update({reset:true});}finally{pending=false;}};}}><label for="new-password">{t("New password")}</label><div class="auth-input"><LockKeyhole size={17}/><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required disabled={pending}/></div><label for="confirmation">{t("Confirm your password")}</label><div class="auth-input"><LockKeyhole size={17}/><input id="confirmation" name="confirmation" type="password" autocomplete="new-password" minlength="8" maxlength="128" required disabled={pending}/></div><button class="primary auth-submit" disabled={pending}>{#if pending}<LoaderCircle size={18} class="spin"/>{t("Saving…")}{:else}{t("Save my new password")}<ArrowRight size={17}/>{/if}</button></form></section></main></div>
